import * as bunTest from 'bun:test';
/**
 * Runs Better Auth's official adapter suite (`@better-auth/test-utils`)
 * against `better-drizzle/auth`.
 *
 * The suite changes the Better Auth options between groups (plugins, custom
 * fields, numeric/uuid ids), so every set of options gets its own Drizzle
 * schema, generated by the adapter's `createSchema` (the Drizzle RQB v2
 * generator), and its tables come from Better Auth's own migrator.
 */
import { createHash } from 'node:crypto';
import { mkdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

import type { BetterAuthOptions } from 'better-auth';
import { getMigrations } from 'better-auth/db/migration';
import { type AnyPlugin, better } from 'better-drizzle';
import { adapter } from 'better-drizzle/auth';
import { Table, defineRelations, is } from 'drizzle-orm';

// Bun runs `vitest` imports as `bun:test`, which does not pass vitest's test
// context (`onTestFailed`, `skip`) that the suite reads. Its tests are
// registered through `test.skipIf()`, so that is where the context is added.
const SKIPPED = Symbol('skipped');
type TestFn = (context: object) => unknown;
Object.assign(bunTest.test, {
	skipIf:
		(condition: boolean) =>
		(name: string, options: { timeout?: number }, fn: TestFn) =>
			condition
				? bunTest.test.skip(name, () => {})
				: bunTest.test(
						name,
						async () => {
							try {
								await fn({
									onTestFailed: () => {},
									skip: () => {
										throw SKIPPED;
									},
								});
							} catch (error) {
								if (error !== SKIPPED) throw error;
							}
						},
						options.timeout,
					),
});

const {
	authFlowTestSuite,
	caseInsensitiveTestSuite,
	joinsTestSuite,
	normalTestSuite,
	numberIdTestSuite,
	testAdapter,
	transactionsTestSuite,
	uuidTestSuite,
} = await import('@better-auth/test-utils/adapter');

export type Dialect = 'sqlite' | 'pg' | 'mysql';

type Setup = {
	dialect: Dialect;
	/** The driver connection Better Auth's migrator reads as `database`. */
	connection: unknown;
	/** Builds a Drizzle client over `connection` for the given relations. */
	drizzle: (relations: object) => { readonly _: { relations: object } };
	/** A one-table schema module, used only to generate the auth schema. */
	placeholder: Record<string, unknown>;
	plugins?: () => readonly AnyPlugin[];
	/** Suites the dialect cannot run, by suite name. */
	skip?: Partial<Record<'numberId' | 'uuid', boolean>>;
	/** Official tests to skip, by `"<group> - <name>"`, with the reason next to them. */
	disable?: Record<string, true>;
	/** Drops every table before migrating, for shared databases. */
	reset?: () => Promise<void>;
};

const dir = join(import.meta.dir, '../../node_modules/.cache/auth-schemas');
const schemas = new Map<string, Promise<Record<string, unknown>>>();

const loadSchema = (setup: Setup, options: BetterAuthOptions) => {
	const placeholder = better(
		setup.drizzle(defineRelations(setup.placeholder)),
	);
	const key = `${setup.dialect}:${JSON.stringify(options, (_, value) =>
		typeof value === 'function' ? String(value) : value,
	)}`;
	let schema = schemas.get(key);
	if (!schema) {
		schema = (async () => {
			const instance = adapter(placeholder, { camelCase: true })(options);
			const { code } = await instance.createSchema!(options);
			const hash = createHash('sha1').update(code).digest('hex');
			const file = join(dir, `${setup.dialect}-${hash.slice(0, 12)}.ts`);
			mkdirSync(dir, { recursive: true });
			writeFileSync(file, code);
			return import(file);
		})();
		schemas.set(key, schema);
	}
	return schema;
};

const createClient = async (setup: Setup, options: BetterAuthOptions) => {
	const module = await loadSchema(setup, options);
	const tables = Object.create(null) as Record<string, Table>;
	for (const name in module)
		if (is(module[name], Table)) tables[name] = module[name] as Table;
	return better(
		setup.drizzle({
			...defineRelations(tables),
			...(module.authRelations as object),
		}),
		{ plugins: setup.plugins?.() ?? [] },
	);
};

// `bun:test` fails `expect(promise).resolves.not.toThrow()` for any resolved
// value; `tests/auth/adapter-behavior.test.ts` covers this case instead.
const disableTests = { 'delete - should not throw on record not found': true };

export const runAdapterSuite = async (setup: Setup) => {
	const disabled = { ...disableTests, ...setup.disable };
	const { execute } = await testAdapter({
		adapter: async (options) =>
			adapter(await createClient(setup, options), { camelCase: true }),
		runMigrations: async (options) => {
			await setup.reset?.();
			const { runMigrations } = await getMigrations({
				...options,
				database: setup.connection as BetterAuthOptions['database'],
			});
			await runMigrations();
		},
		tests: [
			normalTestSuite({ disableTests: disabled }),
			transactionsTestSuite({ disableTests: disabled }),
			authFlowTestSuite({ disableTests: disabled }),
			joinsTestSuite({ disableTests: disabled }),
			caseInsensitiveTestSuite({ disableTests: disabled }),
			...(setup.skip?.uuid
				? []
				: [uuidTestSuite({ disableTests: disabled })]),
			...(setup.skip?.numberId
				? []
				: [numberIdTestSuite({ disableTests: disabled })]),
		],
	});
	execute();
};
